import csv
from collections import defaultdict

catalog={r['timeseries_id']:r for r in csv.DictReader(open(CATALOG_CSV))}
zones={}
for tid,rec in catalog.items():
    name=rec['point_uri'].split('#')[-1]
    z=name.split('.')[0]
    k=name.split('.')[1]
    zones.setdefault(z,{})[k]=tid

vals=list(csv.DictReader(open(VALUES_CSV)))
data=defaultdict(dict)
for v in vals:
    data[v['timeseries_id']][v['timestamp']]=float(v['value'])

def occ(ts):
    h=int(ts[11:13])
    import datetime
    dts=datetime.datetime.fromisoformat(ts)
    return dts.weekday()<5 and (8<=h<18)

mid='2018-06-15'
def means(tid):
    d=data[tid]
    a=[];b=[]
    for t,val in d.items():
        if occ(t):
            (a if t<mid else b).append(val)
    import statistics
    return (statistics.mean(a) if a else None, statistics.mean(b) if b else None, len(a),len(b))

for z in sorted(zones):
    spc=zones[z].get('Zone_Air_Cooling_Temperature_Setpoint')
    sph=zones[z].get('Zone_Air_Heating_Temperature_Setpoint')
    sen=zones[z]['Zone_Air_Temperature_Sensor']
    line=f"{z}: sensor before/after = {means(sen)[:2]}"
    if spc: line+= f" | coolSP={means(spc)[:2]}"
    if sph: line+= f" | heatSP={means(sph)[:2]}"
    print(line)
